#!/usr/bin/env bash
# El banco no puede escribir de forma legible un comando de 12.000 caracteres: lo arma este guion y se lo pasa al
# freno de verdad. El comando es un echo con relleno y, en el renglon siguiente, un cd REAL a un clon de trabajo
# seguido de git add -A; mide exactamente 12001 caracteres (si el largo no da, sale 3 y el freno recibe una
# entrada vacia: el caso queda rojo, no verde).
node -e '
const [work, cwd, size] = process.argv.slice(1);
const q = String.fromCharCode(34);
const tail = String.fromCharCode(10) + "cd " + q + work + q + " && git add -A";
const cmd = "echo " + "a".repeat(Number(size) - 5 - tail.length) + tail;
if (cmd.length !== Number(size)) process.exit(3);
process.stdout.write(JSON.stringify({ tool_name: "Bash", tool_input: { command: cmd }, cwd }));
' "${FIXTURE}/work-clone" "${FIXTURE}/installed-tree" 12001 | bash "${TCG}/scripts/hooks/safety-guard-pre.sh"

